<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
import * as echarts from 'echarts'
import {api} from './api'
interface Stats {total:number;correct:number;wrong:number;unanswered:number;unknown:number;accuracy:number|null;completed:number;completion:number;tags:{code:string;label:string;count:number}[]}
interface ModuleStats extends Stats {module:string}
const props=defineProps<{paperId:string}>(),emit=defineEmits<{openFilter:[filter:string]}>()
const stats=ref<Stats & {trusted:boolean;modules:ModuleStats[]}>(),error=ref(''),chart=ref<HTMLElement>(),module=ref('')
let instance:echarts.ECharts|undefined
function draw(){if(!chart.value||!stats.value)return;instance ||= echarts.init(chart.value);instance.setOption({tooltip:{trigger:'axis'},grid:{left:100,right:30,bottom:40},xAxis:{type:'category',data:stats.value.modules.map(m=>m.module),axisLabel:{interval:0,rotate:20}},yAxis:{type:'value',max:100,axisLabel:{formatter:'{value}%'}},series:[{name:'正确率',type:'bar',data:stats.value.modules.map(m=>m.accuracy),itemStyle:{color:'#367f71'}}]})}
function resize(){instance?.resize()}
onMounted(async()=>{try{stats.value=await api('/analytics/papers/'+props.paperId);await nextTick();draw();window.addEventListener('resize',resize)}catch(e){error.value=String(e)}})
onBeforeUnmount(()=>{instance?.dispose();window.removeEventListener('resize',resize)})
</script>
<template><el-alert v-if="error" :title="error" type="error"/><template v-if="stats"><el-alert v-if="!stats.trusted" title="尚未确认的解析数据，统计仅供核对" type="warning" :closable="false"/><div class="metrics"><article>题目<strong>{{stats.total}}</strong></article><article>正确 / 错误<strong>{{stats.correct}} / {{stats.wrong}}</strong></article><article>正确率<strong>{{stats.accuracy===null?'无法计算':stats.accuracy+'%'}}</strong></article><article>未作答 / 未知<strong>{{stats.unanswered}} / {{stats.unknown}}</strong></article><article>完成复盘<strong>{{stats.completed}} · {{stats.completion}}%</strong></article></div><p>正确率分母仅含明确答对与答错的题目；未知与明确未作答单独统计。</p><div ref="chart" class="chart"/><el-table :data="stats.modules"><el-table-column prop="module" label="模块"/><el-table-column prop="total" label="题量"/><el-table-column prop="correct" label="正确"/><el-table-column prop="wrong" label="错误"/><el-table-column prop="unanswered" label="未作答"/><el-table-column prop="unknown" label="未知"/><el-table-column label="正确率"><template #default="{row}">{{row.accuracy===null?'无法计算':row.accuracy+'%'}}</template></el-table-column><el-table-column label="复盘完成率"><template #default="{row}">{{row.completion}}%</template></el-table-column></el-table><h3>实际记录的标签频次</h3><el-select v-model="module" clearable placeholder="全部模块"><el-option v-for="m in stats.modules" :key="m.module" :value="m.module"/></el-select><p v-if="!(module?stats.modules.find(m=>m.module===module)!.tags:stats.tags).length">尚未记录易错标签</p><p v-for="t in module?stats.modules.find(m=>m.module===module)!.tags:stats.tags" :key="t.code">{{t.label}} <strong>{{t.count}} 题</strong></p><p class="muted">标签统计反映你主动记录的问题，不等于所有错题真实错因分布。</p><el-button @click="emit('openFilter','pending')">待复盘题目</el-button><el-button @click="emit('openFilter','later')">二刷清单</el-button></template></template>
